// devOption allows management of the mutation configuration using functional options.
type devOption func(*DevMutation)

// newDevMutation creates new mutation for the Dev entity.
func newDevMutation(c config, op Op, opts ...devOption) *DevMutation {
	m := &DevMutation{
		config:        c,
		op:            op,
		typ:           TypeDev,
		clearedFields: make(map[string]struct{}),
	}
	for _, opt := range opts {
		opt(m)
	}
	return m
}

// withDevID sets the ID field of the mutation.
func withDevID(id int64) devOption {
	return func(m *DevMutation) {
		var (
			err   error
			once  sync.Once
			value *Dev
		)
		m.oldValue = func(ctx context.Context) (*Dev, error) {
			once.Do(func() {
				if m.done {
					err = errors.New("querying old values post mutation is not allowed")
				} else {
					value, err = m.Client().Dev.Get(ctx, id)
				}
			})
			return value, err
		}
		m.id = &id
	}
}

// withDev sets the old Dev of the mutation.
func withDev(node *Dev) devOption {
	return func(m *DevMutation) {
		m.oldValue = func(context.Context) (*Dev, error) {
			return node, nil
		}
		m.id = &node.ID
	}
}

